-- Private, mutually opted-in direct messages. No anonymous directory or arbitrary account search.
create table if not exists cbgpu_schools.messaging_preferences(user_id uuid primary key references auth.users,allow_direct_messages boolean not null default false,display_name text not null default ''check(length(display_name)<=80),updated_at timestamptz not null default now());
create table if not exists cbgpu_schools.direct_conversations(id uuid primary key default gen_random_uuid(),user_a uuid not null references auth.users,user_b uuid not null references auth.users,scope text not null check(scope in('SCHOOL','NATIONWIDE')),school_id text references cbgpu_schools.schools,created_at timestamptz not null default now(),check(user_a<user_b),check((scope='SCHOOL')=(school_id is not null)));
create unique index if not exists direct_conversation_pair on cbgpu_schools.direct_conversations(scope,coalesce(school_id,''),user_a,user_b);
create table if not exists cbgpu_schools.direct_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references cbgpu_schools.direct_conversations,user_id uuid not null references auth.users,body text not null check(length(body)between 1 and 2000),client_message_id uuid,created_at timestamptz not null default now(),deleted_at timestamptz);
create unique index if not exists direct_message_client on cbgpu_schools.direct_messages(user_id,client_message_id)where client_message_id is not null;
create index if not exists direct_messages_thread on cbgpu_schools.direct_messages(conversation_id,created_at desc)where deleted_at is null;
create table if not exists cbgpu_schools.direct_message_reports(id uuid primary key default gen_random_uuid(),message_id uuid not null references cbgpu_schools.direct_messages,reporter_id uuid not null references auth.users,reason text not null check(length(reason)between 1 and 1000),created_at timestamptz not null default now(),unique(message_id,reporter_id));
alter table cbgpu_schools.messaging_preferences enable row level security;alter table cbgpu_schools.direct_conversations enable row level security;alter table cbgpu_schools.direct_messages enable row level security;alter table cbgpu_schools.direct_message_reports enable row level security;
revoke all on cbgpu_schools.messaging_preferences,cbgpu_schools.direct_conversations,cbgpu_schools.direct_messages,cbgpu_schools.direct_message_reports from public,anon,authenticated,service_role;
create or replace function cbgpu_schools.dm_identity(subject uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from auth.users u join public.profiles p on p.id=u.id where u.id=subject and u.email_confirmed_at is not null and u.deleted_at is null and(u.banned_until is null or u.banned_until<=clock_timestamp())and p.account_status in('ACTIVE','PENDING_VERIFICATION','REVERIFICATION_REQUIRED'))$$;
create or replace function cbgpu_schools.dm_label(subject uuid)returns text language sql stable security definer set search_path='' as $$select coalesce((select nullif(display_name,'')from cbgpu_schools.messaging_preferences where user_id=subject),'Member '||left(replace(subject::text,'-',''),8))$$;
create or replace function cbgpu_schools.dm_scope(subject uuid,channel text,school text)returns boolean language sql stable security definer set search_path='' as $$select cbgpu_schools.dm_identity(subject) and channel in('SCHOOL','NATIONWIDE')and cbgpu_schools.community_allowed(subject,channel,school)$$;
create or replace function cbgpu_schools.dm_blocked(a uuid,b uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from cbgpu_schools.message_mutes where(user_id=a and muted_user_id=b)or(user_id=b and muted_user_id=a))$$;
create or replace function cbgpu_schools.dm_thread_allowed(c cbgpu_schools.direct_conversations,subject uuid)returns boolean language sql stable security definer set search_path='' as $$select subject in(c.user_a,c.user_b)and cbgpu_schools.dm_scope(c.user_a,c.scope,c.school_id)and cbgpu_schools.dm_scope(c.user_b,c.scope,c.school_id)and not cbgpu_schools.dm_blocked(c.user_a,c.user_b)$$;
create or replace function cbgpu_schools.dm_conversation_json(c cbgpu_schools.direct_conversations,subject uuid)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',c.id,'scope',c.scope,'school_id',c.school_id,'peer_id',case when c.user_a=subject then c.user_b else c.user_a end,'peer_label',cbgpu_schools.dm_label(case when c.user_a=subject then c.user_b else c.user_a end),'created_at',c.created_at,'last_message_at',(select max(created_at)from cbgpu_schools.direct_messages where conversation_id=c.id and deleted_at is null))$$;
create or replace function cbgpu_schools.dm_message_json(m cbgpu_schools.direct_messages)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',m.id,'user_id',m.user_id,'sender_label',cbgpu_schools.dm_label(m.user_id),'body',m.body,'created_at',m.created_at,'client_message_id',m.client_message_id)$$;
revoke all on function cbgpu_schools.dm_identity(uuid),cbgpu_schools.dm_label(uuid),cbgpu_schools.dm_scope(uuid,text,text),cbgpu_schools.dm_blocked(uuid,uuid),cbgpu_schools.dm_thread_allowed(cbgpu_schools.direct_conversations,uuid),cbgpu_schools.dm_conversation_json(cbgpu_schools.direct_conversations,uuid),cbgpu_schools.dm_message_json(cbgpu_schools.direct_messages)from public,anon,authenticated,service_role;
create or replace function public.cbgpu_school_direct_messaging_api(action text,payload jsonb default '{}')returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();target uuid;sid text:=payload->>'school_id';channel text:=payload->>'scope';c cbgpu_schools.direct_conversations;m cbgpu_schools.direct_messages;cid uuid;begin
 if not public.cbgpu_personal_project_identity()then raise exception 'AUTHENTICATION_REQUIRED'using errcode='42501';end if;
 if jsonb_typeof(payload)<>'object'or octet_length(payload::text)>16000 then raise exception 'INVALID_REQUEST'using errcode='22023';end if;
 if action='preferences'then if payload<>'{}'::jsonb then raise exception 'INVALID_REQUEST'using errcode='22023';end if;return jsonb_build_object('allow_direct_messages',coalesce((select allow_direct_messages from cbgpu_schools.messaging_preferences where user_id=uid),false),'display_name',coalesce((select display_name from cbgpu_schools.messaging_preferences where user_id=uid),''));
 elsif action='preferences_save'then
 if exists(select 1 from jsonb_object_keys(payload)k where k not in('allow_direct_messages','display_name'))or jsonb_typeof(payload->'allow_direct_messages')is distinct from 'boolean'or jsonb_typeof(payload->'display_name')is distinct from 'string'or length(btrim(payload->>'display_name'))>80 or payload->>'display_name'~'[[:cntrl:]]'then raise exception 'INVALID_MESSAGING_PREFERENCES'using errcode='22023';end if;
 insert into cbgpu_schools.messaging_preferences(user_id,allow_direct_messages,display_name)values(uid,(payload->>'allow_direct_messages')::boolean,btrim(payload->>'display_name'))on conflict(user_id)do update set allow_direct_messages=excluded.allow_direct_messages,display_name=excluded.display_name,updated_at=clock_timestamp();return jsonb_build_object('allow_direct_messages',(payload->>'allow_direct_messages')::boolean,'display_name',btrim(payload->>'display_name'));
 elsif action='recipients'then
 if exists(select 1 from jsonb_object_keys(payload)k where k not in('scope','school_id'))or not cbgpu_schools.dm_scope(uid,channel,sid)or not coalesce((select allow_direct_messages from cbgpu_schools.messaging_preferences where user_id=uid),false)then raise exception 'DIRECT_MESSAGING_NOT_AVAILABLE'using errcode='42501';end if;
 return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('user_id',x.user_id,'sender_label',cbgpu_schools.dm_label(x.user_id))order by x.user_id),'[]')from(select p.user_id from cbgpu_schools.messaging_preferences p where p.user_id<>uid and p.allow_direct_messages and cbgpu_schools.dm_scope(p.user_id,channel,sid)and not cbgpu_schools.dm_blocked(uid,p.user_id)and(channel='SCHOOL'or exists(select 1 from cbgpu_schools.messages posted where posted.user_id=p.user_id and posted.scope='NATIONWIDE'and posted.school_id is null and posted.deleted_at is null))order by p.user_id limit 100)x));
 elsif action='conversations'then return jsonb_build_object('items',(select coalesce(jsonb_agg(cbgpu_schools.dm_conversation_json(x::cbgpu_schools.direct_conversations,uid)order by x.created_at desc),'[]')from(select * from cbgpu_schools.direct_conversations dc where uid in(dc.user_a,dc.user_b)and cbgpu_schools.dm_thread_allowed(dc,uid)order by dc.created_at desc limit 100)x));
 elsif action='conversation_create'then
 if exists(select 1 from jsonb_object_keys(payload)k where k not in('recipient_id','scope','school_id'))then raise exception 'INVALID_REQUEST'using errcode='22023';end if;
 target:=(payload->>'recipient_id')::uuid;
 if target is null or target=uid or not cbgpu_schools.dm_scope(uid,channel,sid)or not cbgpu_schools.dm_scope(target,channel,sid)or cbgpu_schools.dm_blocked(uid,target)or(select count(*)from cbgpu_schools.messaging_preferences where user_id in(uid,target)and allow_direct_messages)<>2 or(channel='NATIONWIDE'and not exists(select 1 from cbgpu_schools.messages where user_id=target and scope='NATIONWIDE'and school_id is null and deleted_at is null))then raise exception 'DIRECT_RECIPIENT_NOT_AVAILABLE'using errcode='P0002';end if;
 perform pg_advisory_xact_lock(hashtextextended('direct-pair:'||least(uid,target)::text||greatest(uid,target)::text||channel||coalesce(sid,''),0));
 select * into c from cbgpu_schools.direct_conversations where user_a=least(uid,target)and user_b=greatest(uid,target)and scope=channel and school_id is not distinct from sid;
 if not found then insert into cbgpu_schools.direct_conversations(user_a,user_b,scope,school_id)values(least(uid,target),greatest(uid,target),channel,sid)returning * into c;end if;
 return jsonb_build_object('conversation',cbgpu_schools.dm_conversation_json(c,uid));
 elsif action in('direct_delete','direct_report')then
 if exists(select 1 from jsonb_object_keys(payload)k where k not in('id','reason'))then raise exception 'INVALID_REQUEST'using errcode='22023';end if;
 select * into m from cbgpu_schools.direct_messages where id=(payload->>'id')::uuid and deleted_at is null for update;
 if not found then raise exception 'DIRECT_MESSAGE_NOT_FOUND'using errcode='P0002';end if;
 if action='direct_delete'and m.user_id=uid then update cbgpu_schools.direct_messages set deleted_at=clock_timestamp()where id=m.id;return jsonb_build_object('ok',true);end if;
 select * into c from cbgpu_schools.direct_conversations where id=m.conversation_id;
 if action<>'direct_report'or not cbgpu_schools.dm_thread_allowed(c,uid)then raise exception 'DIRECT_MESSAGE_NOT_FOUND'using errcode='P0002';end if;
 if jsonb_typeof(payload->'reason')is distinct from 'string'or length(btrim(payload->>'reason'))not between 1 and 1000 then raise exception 'INVALID_REPORT'using errcode='22023';end if;
 insert into cbgpu_schools.direct_message_reports(message_id,reporter_id,reason)values(m.id,uid,btrim(payload->>'reason'))on conflict(message_id,reporter_id)do nothing;return jsonb_build_object('ok',true);
 elsif action in('direct_messages','direct_send')then
 if exists(select 1 from jsonb_object_keys(payload)k where k not in('conversation_id','body','client_message_id'))then raise exception 'INVALID_REQUEST'using errcode='22023';end if;
 select * into c from cbgpu_schools.direct_conversations where id=(payload->>'conversation_id')::uuid;
 if not found or not cbgpu_schools.dm_thread_allowed(c,uid)then raise exception 'DIRECT_CONVERSATION_NOT_FOUND'using errcode='P0002';end if;
 if action='direct_messages'then return jsonb_build_object('items',(select coalesce(jsonb_agg(cbgpu_schools.dm_message_json(x::cbgpu_schools.direct_messages)order by x.created_at,x.id),'[]')from(select * from cbgpu_schools.direct_messages d where d.conversation_id=c.id and d.deleted_at is null order by d.created_at desc,d.id desc limit 100)x));end if;
 if(select count(*)from cbgpu_schools.messaging_preferences where user_id in(c.user_a,c.user_b)and allow_direct_messages)<>2 then raise exception 'DIRECT_MESSAGING_OPTED_OUT'using errcode='42501';end if;
 if jsonb_typeof(payload->'body')is distinct from 'string'or length(btrim(payload->>'body'))not between 1 and 2000 then raise exception 'INVALID_MESSAGE'using errcode='22023';end if;
 if payload?'client_message_id'then cid:=(payload->>'client_message_id')::uuid;if cid is null then raise exception 'INVALID_CLIENT_MESSAGE_ID'using errcode='22023';end if;end if;
 perform pg_advisory_xact_lock(hashtextextended('school-message:'||uid::text,0));
 if cid is not null then select * into m from cbgpu_schools.direct_messages where user_id=uid and client_message_id=cid;if found then if m.conversation_id<>c.id or m.body<>btrim(payload->>'body')or m.deleted_at is not null then raise exception 'MESSAGE_IDEMPOTENCY_CONFLICT'using errcode='23505';end if;return jsonb_build_object('message',cbgpu_schools.dm_message_json(m),'duplicate',true);end if;end if;
 if(select count(*)from cbgpu_schools.direct_messages where user_id=uid and created_at>clock_timestamp()-interval '1 minute')+(select count(*)from cbgpu_schools.messages where user_id=uid and created_at>clock_timestamp()-interval '1 minute')>=10 then raise exception 'MESSAGE_RATE_LIMIT'using errcode='P0429';end if;
 insert into cbgpu_schools.direct_messages(conversation_id,user_id,body,client_message_id)values(c.id,uid,btrim(payload->>'body'),cid)returning * into m;return jsonb_build_object('message',cbgpu_schools.dm_message_json(m),'duplicate',false);
 end if;raise exception 'UNKNOWN_DIRECT_MESSAGING_ACTION'using errcode='22023';end$$;
revoke all on function public.cbgpu_school_direct_messaging_api(text,jsonb)from public,anon,service_role;grant execute on function public.cbgpu_school_direct_messaging_api(text,jsonb)to authenticated;
-- Blocking a known private peer does not require publishing a group message.
-- Both message send paths share one per-user, per-minute admission lock/quota.
do $$declare definition text;changed text;begin
 definition:=pg_get_functiondef('public.cbgpu_school_messenger_api(text,jsonb)'::regprocedure);
 changed:=replace(definition,$a$visible.deleted_at is null and cbgpu_schools.community_allowed(uid,visible.scope,visible.school_id))then$a$,$b$visible.deleted_at is null and cbgpu_schools.community_allowed(uid,visible.scope,visible.school_id))and not exists(select 1 from cbgpu_schools.direct_conversations known where uid in(known.user_a,known.user_b)and muted in(known.user_a,known.user_b))then$b$);
 changed:=replace(changed,$a$created_at>clock_timestamp()-interval '1 minute')>=10$a$,$b$created_at>clock_timestamp()-interval '1 minute')+(select count(*)from cbgpu_schools.direct_messages where user_id=uid and created_at>clock_timestamp()-interval '1 minute')>=10$b$);
 if changed=definition and position('direct_conversations known'in definition)=0 then raise exception 'DIRECT_MESSAGE_COMPAT_SOURCE_MISMATCH';end if;execute changed;
end$$;
